NEW = {"tools/tests/portfolio_tax/test_portfolio_tax.py": "", "tools/tests/portfolio_tax/unit.mjs": ""}
MIRROR = os.path.join(ROOT, "desktop/src-tauri/frontend/src", REL[len("frontend/src/"):])


def die(m):
    print("\nABORT:", m); sys.exit(1)


print(f"── {FENCE}")
for rel, marker in PREREQ.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        die(f"{rel} not found — run from the repo root")
    t = open(p, encoding="utf-8").read()
    if FENCE in t:
        die(f"{FENCE} already applied ({rel})")
    if marker not in t:
        die(f"prerequisite '{marker}' missing in {rel}")
for rel in NEW:
    if os.path.exists(os.path.join(ROOT, rel)):
        die(f"{rel} already exists — remove the hand-placed copy and re-run")
p = os.path.join(ROOT, REL)
t = open(p, encoding="utf-8").read()
for old, new in OPS:
    n = t.count(old)
    if n != 1:
        die(f"{REL}: anchor found {n}x (need 1): {old.strip().splitlines()[0][:80]!r}")
    t = t.replace(old, new)
st = subprocess.run(["git", "status", "--porcelain", "--", REL], cwd=ROOT, capture_output=True, text=True).stdout
if [l for l in st.splitlines() if l.strip() and not l.startswith("??")] and "--allow-dirty" not in sys.argv:
    die(f"uncommitted changes on {REL}; commit them or re-run with --allow-dirty")

shutil.copy2(p, p + f".bak-{FENCE}")
open(p, "w", encoding="utf-8").write(t)
mirrored = os.path.isdir(os.path.dirname(MIRROR))
if mirrored:
    open(MIRROR, "w", encoding="utf-8").write(t)
for rel, b64 in NEW.items():
    q = os.path.join(ROOT, rel)
    os.makedirs(os.path.dirname(q), exist_ok=True)
    open(q, "wb").write(base64.b64decode(b64))
open(os.path.join(ROOT, f".{FENCE}.done"), "w").write("applied\n")
print(f"   edited {REL} ({len(OPS)} hunks; backup .bak-{FENCE}{'; desktop mirror updated' if mirrored else ''}), created {len(NEW)} test files")


def rollback(reason):
    shutil.move(p + f".bak-{FENCE}", p)
    if mirrored:
        shutil.copy2(p, MIRROR)
    for rel in NEW:
        q = os.path.join(ROOT, rel)
        if os.path.exists(q):
            os.remove(q)
    d = os.path.join(ROOT, "tools/tests/portfolio_tax")
    if os.path.isdir(d) and not os.listdir(d):
        os.rmdir(d)
    os.remove(os.path.join(ROOT, f".{FENCE}.done"))
    die(reason)


esb = os.environ.get("ESBUILD") or os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")
if not os.path.exists(esb):
    esb = shutil.which("esbuild")
if esb:
    r = subprocess.run([esb, REL, "--loader:.jsx=jsx", "--jsx=automatic", "--log-level=error", "--outfile=/dev/null"],
                       cwd=ROOT, capture_output=True, text=True)
    if r.returncode != 0:
        rollback("esbuild parse failed; restored:\n" + r.stderr[-1500:])
    print(f"   esbuild ok {REL}")
r = subprocess.run([sys.executable, "tools/tests/portfolio_tax/test_portfolio_tax.py"], cwd=ROOT,
                   capture_output=True, text=True, timeout=600)
tail = (r.stdout.strip().splitlines() or [""])[-1]
print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} tools/tests/portfolio_tax/test_portfolio_tax.py — {tail[:90]}")
if r.returncode != 0:
    print("\n".join(l for l in r.stdout.splitlines() if "FAIL" in l)[-3000:])
    print((r.stderr or "")[-2000:])
    rollback("portfolio tax checks failed; working copy restored")
print(f"── {FENCE} applied. Next: ./desktop/build-scalp.sh frontend")
